package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.entity.CardFile;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelist12.WSAccountPayDocInCardfileList12PortType;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelist12.WSAccountPayDocInCardfileListGetResponseType;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelistinoutparms12.WSAccountPayDocInCardfileListGetInParms;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelistinoutparms12.WSAccountPayDocInCardfileListGetOutParms;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelistinoutparms12.WSAccountPayDocInCardfileListGetOutResultSet;
import ru.alfabank.ws.cs.eq.wsaccountpaydocincardfilelistinoutparms12.WSAccountPayDocInCardfileListGetOutResultSetRow;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

@Component
@RequiredArgsConstructor
public class AccountCardFileListGateway {

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSAccountPayDocInCardfileList12PortType wsAccountPayDocInCardfileList12PortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<CardFile> getCardFiles(String accountNumber) {
        WSAccountPayDocInCardfileListGetInParms inParms = new WSAccountPayDocInCardfileListGetInParms();
        inParms.setEan(accountNumber);
        return convertToCardFiles(wsAccountPayDocInCardfileList12PortType
                .wsAccountPayDocInCardfileListGet(commonParms.getObject(), inParms));
    }

    private List<CardFile> convertToCardFiles(WSAccountPayDocInCardfileListGetResponseType from) {
        final Map<String, List<CardFile.PaymentDocument>> paymentDocumentsGroupedByNumber = Optional.ofNullable(from)
                .map(WSAccountPayDocInCardfileListGetResponseType::getOutParms)
                .map(WSAccountPayDocInCardfileListGetOutParms::getResultSet)
                .map(WSAccountPayDocInCardfileListGetOutResultSet::getResultSetRow)
                .orElseGet(Collections::emptyList)
                .stream()
                .map(AccountCardFileListGateway::convertToPaymentDocument)
                .collect(Collectors.groupingBy(CardFile.PaymentDocument::getCardFileNumber, Collectors.toList()));

        if (paymentDocumentsGroupedByNumber.isEmpty()) {
            return Collections.emptyList();
        }

        final List<CardFile> cardFiles = new ArrayList<>();

        final WSAccountPayDocInCardfileListGetOutParms wsOutParms = from.getOutParms();

        if (paymentDocumentsGroupedByNumber.containsKey(wsOutParms.getCrd1())) {
            cardFiles.add(
                    CardFile.builder()
                            .number(wsOutParms.getCrd1())
                            .amount(wsOutParms.getScr1())
                            .unpaidRestAmount(wsOutParms.getSno1())
                            .amountOfSuspendedDocuments(wsOutParms.getSpd1())
                            .documents(paymentDocumentsGroupedByNumber.get(wsOutParms.getCrd1()))
                            .build());
        }

        if (paymentDocumentsGroupedByNumber.containsKey(wsOutParms.getCrd2())) {
            cardFiles.add(
                    CardFile.builder()
                            .number(wsOutParms.getCrd2())
                            .amount(wsOutParms.getScr2())
                            .unpaidRestAmount(wsOutParms.getSno2())
                            .amountOfSuspendedDocuments(wsOutParms.getSpd2())
                            .documents(paymentDocumentsGroupedByNumber.get(wsOutParms.getCrd2()))
                            .build());
        }

        if (paymentDocumentsGroupedByNumber.containsKey(wsOutParms.getCrd3())) {
            cardFiles.add(
                    CardFile.builder()
                            .number(wsOutParms.getCrd3())
                            .amount(wsOutParms.getScr3())
                            .unpaidRestAmount(wsOutParms.getSno3())
                            .amountOfSuspendedDocuments(wsOutParms.getSpd3())
                            .documents(paymentDocumentsGroupedByNumber.get(wsOutParms.getCrd3()))
                            .build());
        }

        return cardFiles;
    }

    private static CardFile.PaymentDocument convertToPaymentDocument(WSAccountPayDocInCardfileListGetOutResultSetRow from) {
        return CardFile.PaymentDocument.builder()
                .id(from.getDocid())
                .type(from.getRtyp())
                .number(from.getR201())
                .cardFileNumber(from.getRcrd())
                .amount(from.getR320())
                .reservedAmount(from.getR321())
                .restAmount(from.getR322())
                .sender(
                        CardFile.Subject.builder()
                                .name(from.getR50Ae())
                                .inn(from.getR500())
                                .pin(from.getRpin())
                                .build()
                )
                .receiver(
                        CardFile.Subject.builder()
                                .name(from.getR59Ae())
                                .inn(from.getR590())
                                .build()
                )
                .paymentInfo(from.getR700())
                .paymentOrder(StringUtils.isEmpty(from.getR702()) ? null : Integer.parseInt(from.getR702()))
                .paymentCreditorOrder(StringUtils.isEmpty(from.getRpun()) ? null : Integer.parseInt(from.getRpun()))
                .termOfAcceptInDay(from.getR207().intValue())
                .currency(from.getR105())
                .status(from.getRsts())
                .primaryDate(from.getR301() == null ? null : from.getR301())
                .cardFileDate(from.getRdcr() == null ? null : from.getRdcr())
                .createDateTime(aggregateDateTime(from.getRdt1(), from.getRtm1()))
                .build();
    }

    private static LocalDateTime aggregateDateTime(LocalDate date, String time) {
        if (date == null) {
            return null;
        }
        final long nanoTime = StringUtils.isBlank(time) ? 0 : LocalTime.parse(time).toNanoOfDay();
        return date.atStartOfDay().plusNanos(nanoTime);
    }

}```

