package ru.alfabank.api.accounts.util;

import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Text;
import ru.alfabank.api.accounts.entity.CustomerAccountCreationRequest;
import ru.alfabank.api.utils.exception.service.SystemServiceException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.OutputKeys;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerException;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.StringWriter;

@Slf4j
public class XmlFormatter {

    public static String getFreeFormat(String cardNumber, String eventType, CustomerAccountCreationRequest request) {
        try {
            final Document document = DocumentBuilderFactory.newInstance()
                    .newDocumentBuilder()
                    .newDocument();
            final Element rootElement = document.createElement("m");
            addTextNode(document, rootElement, "ga", cardNumber);
            addTextNode(document, rootElement, "mc", eventType);
            addTextNode(document, rootElement, "callerId", request.getCallerId());
            addTextNode(document, rootElement, "callerEntityId", request.getCallerEntityId());
            addTextNode(document, rootElement, "accType", request.getAccountType());
            if (request.getOperatorPosition() != null) {
                addTextNode(document, rootElement, "operatorPosition", request.getOperatorPosition());
            }
            if ("FY".equals(request.getAccountType()) || "ET".equals(request.getAccountType()) || "VW".equals(request.getAccountType())) {
                addTextNode(document, rootElement, "accountGroup", "Накопительные счета");
            }
            if (request.getAccountTypeName() != null) {
                addTextNode(document, rootElement, "accountCurrency", request.getCurrencyCode());
                addTextNode(document, rootElement, "accountName", request.getAccountTypeName());
                addTextNode(document, rootElement, "accountNumber", StringUtils.leftPad(StringUtils.right(cardNumber, 4), cardNumber.length(), "*"));
                addTextNode(document, rootElement, "accountPlannedSum", request.getAccountPlannedSum());
                addTextNode(document, rootElement, "accountNewCash", request.getAccountNewCash());
            }
            if (request.isConfidant()) {
                addTextNode(document, rootElement, "isConfidant", "Y");
            }
            final StringWriter writer = new StringWriter();
            final TransformerFactory tf = TransformerFactory.newInstance();
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
            final Transformer transformer = tf.newTransformer();

            transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
            transformer
                    .transform(new DOMSource(rootElement), new StreamResult(writer));
            return writer.toString();
        } catch (ParserConfigurationException | TransformerException e) {
            log.error("Could not build XML document", e);
            throw new SystemServiceException("XmlBuildError", e.getMessage());
        }
    }

    private static void addTextNode(Document document, Element target, String nodeName, String text) {
        if (StringUtils.isNotBlank(text)) {
            final Text textNode = document.createTextNode(text);
            final Element node = document.createElement(nodeName);
            node.appendChild(textNode);
            target.appendChild(node);
        }
    }

}
