package ru.alfabank.api.accounts.ws;

import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.configuration.UwsBasicAuthProperties;
import ru.alfalab.cxf.starter.CxfClientsProperties;

import java.util.List;

/**
 * BeanPostProcessor, который автоматически устанавливает username и password
 * для клиентов CXF при включенной Basic Auth.
 */

@Component
@ConditionalOnProperty("uws.basic-auth.enabled")
@RequiredArgsConstructor
public class CxfClientsBasicAuthBeanPostProcessor implements BeanPostProcessor {

    private final UwsBasicAuthProperties uwsBasicAuthProperties;

    @Override
    public Object postProcessBeforeInitialization(Object bean, String beanName) {
        if (bean.getClass() == CxfClientsProperties.class) {
            List<CxfClientsProperties.WSClient> clients = ((CxfClientsProperties) bean).getClients();
            for (CxfClientsProperties.WSClient client : clients) {
                client.setUserName(uwsBasicAuthProperties.getLogin());
                client.setPassword(uwsBasicAuthProperties.getPassword());
            }
        }
        return bean;
    }
}
