import ru.alfabank.api.accounts.entity.BicInfo;
import ru.alfabank.api.accounts.entity.BranchInfo;
import ru.alfabank.api.accounts.gateway.CodeBicInfoGateway;
import ru.alfabank.api.accounts.gateway.CodeBranchInfoGateway;
import ru.alfabank.api.accounts.mapper.BicInfoMapper;
import ru.alfabank.api.accounts.mapper.BranchInfoMapper;

@Slf4j
@Service
@RequiredArgsConstructor
public class BranchInfoService {

    private final CodeBranchInfoGateway codeBranchInfoGateway;
    private final CodeBicInfoGateway codeBicInfoGateway;
    private final BranchInfoMapper branchInfoMapper;
    private final BicInfoMapper bicInfoMapper;

    public BranchInfo getBranchInfo(String branchId) {
        final BranchInfo branchInfo = branchInfoMapper.mapToBranchInfo(codeBranchInfoGateway.getBranchInfo(branchId));
        if (branchInfo != null) {
            final BicInfo subsidiaryBicInfo = bicInfoMapper.mapToBicInfo(codeBicInfoGateway.getBicInfo(branchInfo.getBic()));
            if (subsidiaryBicInfo != null) {
                final BicInfo rkcBicInfo = bicInfoMapper.mapToBicInfo(codeBicInfoGateway.getBicInfo(subsidiaryBicInfo.getRkcBic()));
                final String rkcName = rkcBicInfo == null ? null : rkcBicInfo.getName();

                branchInfo.setSubsidiaryName(subsidiaryBicInfo.getName())
                        .setCorrespondentAccount(subsidiaryBicInfo.getCorrespondentAccount())
                        .setOkpo(subsidiaryBicInfo.getOkpo())
                        .setRkcName(rkcName);
            }
        }
        return branchInfo;
    }
}
