@Slf4j
@Component
@RequiredArgsConstructor
public class CardAccountTypeCardContractListGateway {

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSCardAccountTypeCardContractListPortType wsCardAccountTypeCardContractListPortType;

    /**
     * Возвращает список типов счетов доступных для карточного контракта
     *
     * @param contractCode         - код карточного контракта
     * @param restrictAccountTypes - типы счетов которые нужно исключить из выдачи
     * @return
     */
    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<CardAccountType> getCardAccountTypes(String contractCode, List<String> restrictAccountTypes) {
        WSCardAccountTypeCardContractListGetInParms inParms = new WSCardAccountTypeCardContractListGetInParms();
        inParms.setScon(contractCode);
        List<CardAccountType> cardAccountTypes = convert(wsCardAccountTypeCardContractListPortType
                .wsCardAccountTypeCardContractListGet(commonParms.getObject(), inParms));

        if (CollectionUtils.isNotEmpty(restrictAccountTypes)) {
            cardAccountTypes = cardAccountTypes.stream()
                    .filter(at -> !restrictAccountTypes.contains(at.getType()))
                    .collect(Collectors.toList());
        }
        return cardAccountTypes;
    }

    private List<CardAccountType> convert(WSCardAccountTypeCardContractListGetOutParms from) {
        return Optional.ofNullable(from)
                .map(WSCardAccountTypeCardContractListGetOutParms::getResultSet)
                .map(WSCardAccountTypeCardContractListGetOutResultSet::getRow)
                .map(r -> r.stream().filter(Objects::nonNull)
                        .map(rs -> new CardAccountType(rs.getShnm(), rs.getAtp())).collect(toList()))
                .orElse(Collections.emptyList());
    }

}
