package ru.alfabank.api.accounts.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import ru.alfabank.api.accounts.dto.AccountingEntriesInfoRequest;
import ru.alfabank.api.accounts.entity.Account;
import ru.alfabank.api.accounts.entity.AccountingEntriesInfo;
import ru.alfabank.api.accounts.gateway.AccountMovementListGateway;
import ru.alfabank.api.utils.exception.service.SystemServiceException;
import io.reactivex.rxjava3.core.Observable;
import ru.alfabank.ws.cs.wscommontypes10.WSAppTechnicalException;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;

/**
 * Операции над бухгалтерскими проводками
 */

@Service
@Slf4j
public class AccountingEntryService {

    private static final List<String> UNSUPPORTED_ACCOUNT_TYPES = Arrays.asList("CN", "GE", "CO", "CM", "K1", "IM", "KF", "N7", "AJ", "BC", "K0", "B0", "BI", "A0");
    private static final String UNSUPPORTED_ACCOUNTING_MODE = "500";
    private static final String NON_CORPORATE_ACCOUNT_ERROR_CODE = "STA0023";

    private final AccountMovementListGateway accountMovementListGateway;

    @Autowired
    public AccountingEntryService(AccountMovementListGateway accountMovementListGateway) {
        this.accountMovementListGateway = accountMovementListGateway;
    }

    public AccountingEntriesInfo getAccountingEntryInfo(AccountingEntriesInfoRequest accountingEntriesInfoRequest) {
        log.info("#getAccountingEntryInfo: accountingEntriesInfoRequest = {}", accountingEntriesInfoRequest);

        if (accountingEntriesInfoRequest.getStartDate().isAfter(accountingEntriesInfoRequest.getEndDate())) {
            throw new IllegalArgumentException("startDate cannot be later endDate");
        }

        try {
            final Optional<AccountingEntriesInfo> accountingEntriesInfo = accountMovementListGateway.getAccountingEntriesInfo(accountingEntriesInfoRequest);
            log.info("#getAccountingEntryInfo: accountingEntryInfo = {}", accountingEntriesInfo);
            return accountingEntriesInfo.orElse(null);
        } catch (Exception e) {
            log.error("An error occurred while querying data from AccountMovementListGateway. Details: {}", e);
            throw new SystemServiceException("AccountMovementError", "An error occurred while querying data from AccountMovementListGateway.");
        }
    }

    public Observable<LocalDate> getLastTransactionDate(Account account) {
        // Сервис не предоставляет информацию по таким счетам
        if (UNSUPPORTED_ACCOUNT_TYPES.contains(account.getAct()) || UNSUPPORTED_ACCOUNTING_MODE.equals(account.getAccountingMode())) {
            return Observable.empty();
        }
        return accountMovementListGateway.getLastTransactionDate(account.getAccountNumber()).onErrorResumeNext(throwable -> {
            // Список не корпоративных типов счетов может измениться в сервисе
            // вэб сервис кидает именно deprecated WSAppTechnicalException
            if (throwable instanceof WSAppTechnicalException cause) {
                if (cause.getFaultInfo() != null && NON_CORPORATE_ACCOUNT_ERROR_CODE.equals(cause.getFaultInfo().getErrorCode())) {
                    log.warn("#getLastTransactionDate: account with act = {} is not corporate - impossible to get last transaction date", account.getAct());
                    return Observable.empty();
                }
            }
            return Observable.error(throwable);
        });
    }
}```

