import ru.alfabank.ws.cs.eq.wscustomernewaccountrestrictionsinoutparms10.WSCustomerNewAccountRestrictionsGetOutParms;
import ru.alfabank.ws.cs.eq.wscustomernewaccountrestrictionsinoutparms10.WSCustomerNewAccountRestrictionsGetOutRecordSet;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

@Component
@RequiredArgsConstructor
public class CustomerNewAccountRestrictionsGateway {
    @Value("${was.wscustomernewaccountrestrictions.externalSystem}")
    private String externalSystem;

    private final ObjectFactory<WSCommonParms> wsCommonParms;
    private final WSCustomerNewAccountRestrictions10PortType wsCustomerNewAccountRestrictions10PortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<AccountRestrictions> getAccountRestrictions(String pinEq) {
        WSCustomerNewAccountRestrictionsGetResponseType response = wsCustomerNewAccountRestrictions10PortType.wsCustomerNewAccountRestrictionsGet(wsCommonParms.getObject(),
                WSCustomerNewAccountRestrictionsGetInParms.builder()
                        .cus(pinEq)
                        .xm(externalSystem)
                        .build());

        return Optional.ofNullable(response)
                .map(WSCustomerNewAccountRestrictionsGetResponseType::getOutParms)
                .map(WSCustomerNewAccountRestrictionsGetOutParms::getResultSet)
                .map(WSCustomerNewAccountRestrictionsGetOutRecordSet::getRecordSetRow)
                .orElse(Collections.emptyList())
                .stream()
                .map(AccountRestrictions::convert)
                .collect(Collectors.toList());
    }
}
