    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<FormerAccount> getMigrationAccounts(String pinEq) {
        WSCustomerMigrationProductsGetListResponseType response = wsCustomerMigrationProducts10PortType.wsCustomerMigrationProductsGetList(wsCommonParms.getObject(),
                WSCustomerMigrationProductsGetListInParms.builder()
                        .cus(pinEq)
                        .prt(MIGRATION_PRODUCTS_PRT)
                        .build());

        return Optional.ofNullable(response)
                .map(WSCustomerMigrationProductsGetListResponseType::getOutParms)
                .map(WSCustomerMigrationProductsGetListOutParms::getResultSet)
                .map(WSCustomerMigrationProductsGetListOutResultSet::getResultSetRow)
                .orElse(Collections.emptyList())
                .stream()
                .map(CustomerMigrationProductsGateway::convert)
                .collect(Collectors.toList());
