        if (operatorCode == null && operatorFullName == null)
            throw new SystemServiceException("AddInfValueInfoError", "operatorCode and operatorFullName cannot be both null.");
        return operatorCode == null ?
                getAddInfValueInfoByFullName(operatorType, operatorFullName) :
                getAddInfValueInfoByCode(operatorType, operatorCode);

