public class AccountV2Service {

    private final UWSCustomerAccounts11Client uwsCustomerAccounts11Client;

    private final UWSCustomerAccounts11ClientMapper mapper;

    public List<AccountV2> getAccountV2ListByParams(
            String customerId,
            String customerLocation,
            String accountNumber,
            String[] accountTypeList,
            String onlyActive,
            String nonZero,
            String[] additionalParams) {

        List<CustomerAccountsResponse> accountV2ListResponse = uwsCustomerAccounts11Client
