import io.swagger.v3.oas.annotations.Operation;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import ru.alfabank.api.accounts.dto.CumulativeHold;
import ru.alfabank.api.accounts.dto.Hold;
import ru.alfabank.api.accounts.entity.PaymentDocumentHold;
import ru.alfabank.api.accounts.service.HoldService;
import ru.alfabank.ufr.methodslog.Log;
import ru.alfabank.ufr.methodslog.SecurityEventType;
import ru.alfabank.ufr.methodslog.annotation.Mask;

import java.util.List;

import static ru.alfabank.ufr.methodslog.MaskType.ACCOUNT_NUMBER;

@RestController
@RequestMapping(produces = MediaType.APPLICATION_JSON_VALUE)
public class HoldController {

    private final HoldService holdService;

    @Autowired
    public HoldController(HoldService holdService
    ) {
        this.holdService = holdService;
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение информации по основным холдам")
    @GetMapping(value = "/accounts/{accountNumber}/majorHolds")
    public ResponseEntity<List<Hold>> getHolds(@PathVariable("accountNumber") @Mask(ACCOUNT_NUMBER) String accountNumber) {
        final List<Hold> holds = holdService.getHolds(accountNumber);
        return new ResponseEntity<>(holds, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение информации по кумулятивным холдам по картам")
    @GetMapping(value = "/accounts/{accountNumber}/cumulativeHolds")
    public ResponseEntity<List<CumulativeHold>> getCumulativeHolds(
            @PathVariable("accountNumber") @Mask(ACCOUNT_NUMBER) String accountNumber) {

        final List<CumulativeHold> holds = holdService.getCumulativeHolds(accountNumber);
        return new ResponseEntity<>(holds, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение информации по кумулятивным холдам по операциям")
    @GetMapping(value = "/accounts/{accountNumber}/payDocHolds")
    public ResponseEntity<List<PaymentDocumentHold>> getPaymentDocumentHolds(
            @PathVariable("accountNumber") @Mask(ACCOUNT_NUMBER) String accountNumber) {

        final List<PaymentDocumentHold> paymentDocumentHolds = holdService.getPaymentDocumentHolds(accountNumber);
        return new ResponseEntity<>(paymentDocumentHolds, HttpStatus.OK);
    }
}
