    private final ObjectFactory<WSCommonParms> commonParms;
    private final UWSAccountBalance11PortType portType;

    private final AccountBalanceGetParamsMapper getParamsMapper;

    /**
     * Получение специальных остатков по счетам
     *
     * @param accountNumberList список счетов по которым требуется определение остатка
     * @param balanceTypeList   список типов остатка которые необходимо определить
     * @return список остатков по счетам
     */
    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<AccountBalance> getAccountBalance(Set<String> accountNumberList, Set<BalanceType> balanceTypeList) {
        UWSAccountBalanceGetInParms inParams = getParamsMapper.mapToGetParams(
                getParamsMapper.mapToUwsList(accountNumberList, ACCOUNT_NUMBER_VALUE_LENGTH, ACCOUNT_NUMBER_VALUE_EXTRACTOR),
                getParamsMapper.mapToUwsList(balanceTypeList, BALANCE_TYPE_VALUE_LENGTH, BALANCE_TYPE_VALUE_EXTRACTOR));

        log.info("#getAccountBalance() inParams = {}", inParams);
        List<AccountBalance> response = Optional.ofNullable(portType.uwsAccountBalanceGet(commonParms.getObject(), inParams))
                .map(UWSAccountBalanceGetResponseType::getOutParms)
                .map(UWSAccountBalanceGetOutParms::getResultSet)
                .map(UWSAccountBalanceGetOutResultSet::getResultSetRow)
                .map(getParamsMapper::mapToAccountBalanceList)
