        if (extractBoolean(from.getK01())) {
            availableCardFiles.add(CardFileType.K01);
        }
        if (extractBoolean(from.getK02())) {
            availableCardFiles.add(CardFileType.K02);
        }
        if (extractBoolean(from.getK11())) {
            availableCardFiles.add(CardFileType.K11);
        }

        return availableCardFiles;
    }

    default String createSqlForEQ(OperationType operationType, String[] acts, String[] ean, LocalDate date) {
        String sql;
        QueryBuilder queryBuilder = new QueryBuilder();
        boolean hasSql = operationType != null && !isEmpty(operationType.getSql());
        boolean hasActs = isNotEmpty(acts) || operationType != null && isNotEmpty(operationType.getSCACT());
        boolean hasEans = isNotEmpty(ean);

        if (hasActs) {
            if (operationType != null) {
                acts = ArrayUtils.addAll(acts, operationType.getSCACT());
            }
            queryBuilder.withActIn(acts);
        }
        if (hasEans) {
            if (hasActs) {
                queryBuilder.and();
            }
            queryBuilder.withEanStartsWith(ean);
        }
        if (hasSql) {
            if (StringUtils.isNotEmpty(queryBuilder.toSql())) {
                queryBuilder.and();
            }
            queryBuilder.withSql(replaceCurrentDateInSQLForEQ(operationType.getSql(), date));
        }
        sql = queryBuilder.toSql();
        log.debug("result SQL for EQ is -- {} --", sql);
        return sql;
    }

    default String replaceCurrentDateInSQLForEQ(String sql, LocalDate now) {
        return sql.replaceAll("%CURRENT_DATE%", getDateForEQ(now));
    }

    default String getDateForEQ(LocalDate date) {
        return String.format("1%02d%02d%02d", (date.getYear() - 2000), date.getMonthValue(), date.getDayOfMonth());
    }

    @Getter
    @AllArgsConstructor
    class OperationTypeDto {
        OperationType operationType;
        String[] acts;
        String[] ean;
    }
