@RequiredArgsConstructor
public class AccountPayDocCumulativeHoldGateway {
    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSAccountPayDocCumulativeHold11PortType wsAccountPayDocCumulativeHold11PortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<PaymentDocumentHold> getPaymentDocumentHolds(String accountNumber) {
        return convert(wsAccountPayDocCumulativeHold11PortType.wsAccountPayDocCumulativeHoldGet(commonParms.getObject(),
                WSAccountPayDocCumulativeHoldGetInParms.builder()
                        .ean(accountNumber)
                        .build()));
    }

    private List<PaymentDocumentHold> convert(WSAccountPayDocCumulativeHoldGetResponseType responseType) {
        return Optional.ofNullable(responseType)
                .map(WSAccountPayDocCumulativeHoldGetResponseType::getOutParms)
                .map(WSAccountPayDocCumulativeHoldGetOutParms::getResultSet)
                .map(WSAccountPayDocCumulativeHoldGetOutResultSet::getResultSetRow)
                .orElseGet(Collections::emptyList)
                .stream()
                .map(this::convert)
                .collect(Collectors.toList());
    }

    private PaymentDocumentHold convert(WSAccountPayDocCumulativeHoldGetOutResultSetRow resultSetRow) {
        return new PaymentDocumentHold()
                .setDocumentId(resultSetRow.getDocid())
                .setHold(resultSetRow.getHld())
                .setAmountToPay(resultSetRow.getR320())
                .setDocumentType(resultSetRow.getRtyp())
                .setDocumentNumber(resultSetRow.getR201())
                .setDocumentDate(resultSetRow.getR301() == null ? null : resultSetRow.getR301())
                .setReceiverName(resultSetRow.getR59Ae())
                .setReceiverINN(resultSetRow.getR590())
                .setReceiverKPP(resultSetRow.getR596())
                .setReceiverAccount(resultSetRow.getR592())
                .setReceiverBIC(resultSetRow.getR557())
                .setReceiverBankName(resultSetRow.getR55Ab())
                .setPaymentPurpose(resultSetRow.getR700())
