@Slf4j
@Component
@RequiredArgsConstructor
public class AccountMovementListGateway {

    private static final String NO_DATE_STRING = "0001-01-01";

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSAccountMovementList16PortType wsAccountMovementList16PortType;
    private final AccountEntryNumberExtractor accountEntryNumberExtractor;

    @CircuitBreaker(name = "wsCircuitBreaker")
    public Observable<LocalDate> getLastTransactionDate(String accountNumber) {
        return Observable.fromCallable(() -> wsAccountMovementList16PortType.wsAccountMovementListGet(commonParms.getObject(),
                        WSAccountMovementListGetInParms.builder()
                                .ean(accountNumber)
                                .vfrs(null)
                                .vfre(null)
                                .build()))
                .map(WSAccountMovementListGetResponseType::getOutParms)
                .filter(Objects::nonNull)
                .flatMap(outParms -> {
                    var lastTransactionDate = outParms.getVfrl();
                    if (lastTransactionDate == null || NO_DATE_STRING.equals(lastTransactionDate.toString())) {
                        return Observable.empty();
                    }
                    return Observable.just(lastTransactionDate);
                });
    }

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public Optional<AccountingEntriesInfo> getAccountingEntriesInfo(AccountingEntriesInfoRequest accountingEntriesInfoRequest) {

        WSAccountMovementListGetResponseType wsResponse = wsAccountMovementList16PortType.wsAccountMovementListGet(commonParms.getObject(),
                WSAccountMovementListGetInParms.builder()
                        .ean(accountingEntriesInfoRequest.getAccountNumber())
                        .vfrs(accountingEntriesInfoRequest.getStartDate())
                        .vfre(accountingEntriesInfoRequest.getEndDate())
                        .ptyp(accountingEntriesInfoRequest.getPaymentType())
                        .r320S(accountingEntriesInfoRequest.getStartAmount())
                        .r320E(accountingEntriesInfoRequest.getEndAmount())
                        .cinn(accountingEntriesInfoRequest.getContractorInn())
                        .cean(accountingEntriesInfoRequest.getContractorAccountNumber())
                        .cnam(accountingEntriesInfoRequest.getContractorName())
                        .r100(accountingEntriesInfoRequest.getDocType())
                        .r233(accountingEntriesInfoRequest.getDebtorCode())
                        .cbnam(accountingEntriesInfoRequest.getContractorBankName())
                        .cbik(accountingEntriesInfoRequest.getContractorBankBik())
                        .build());

        return Optional.ofNullable(wsResponse)
                .map(WSAccountMovementListGetResponseType::getOutParms)
                .map(this::convert);
    }

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public Optional<AccountingInfo> getAccountingInfo(String accountNumber) {
        WSAccountMovementListGetResponseType wsResponse = wsAccountMovementList16PortType.wsAccountMovementListGet(
                commonParms.getObject(), WSAccountMovementListGetInParms.builder()
                        .ean(accountNumber)
                        .build());

        return Optional.ofNullable(wsResponse)
                .map(WSAccountMovementListGetResponseType::getOutParms)
                .map(AccountMovementListGateway::convertToAccountingInfo);
    }

    private AccountingEntriesInfo convert(WSAccountMovementListGetOutParms from) {
        return AccountingEntriesInfo.builder()
                .accountingInfo(
                        AccountingInfo.builder()
                                .incomingBalance(from.getBvv())
                                .outgoingBalance(from.getBiv())
                                .totalDebits(from.getPdv())
                                .totalCredits(from.getPkv())
                                .lastTransactionDate(from.getVfrl())
                                .build()
                )
                .accountingEntries(
                        Optional.ofNullable(from.getResultSet())
                                .map(WSAccountMovementListGetOutResultSet::getResultSetRow)
                                .orElseGet(Collections::emptyList)
                                .stream()
                                .map(this::convert)
                                .collect(Collectors.toList())
                )
                .build();
    }

    private AccountingEntriesInfo.AccountingEntry convert(WSAccountMovementListGetOutResultSetRow from) {
        return AccountingEntriesInfo.AccountingEntry.builder()
                .id(from.getPstky())
                .type(from.getPtyp())
                .code(from.getR100())
                .subtype(from.getR900())
                .contractor(
                        AccountingEntriesInfo.Subject.builder()
                                .name(from.getCnam())
                                .inn(from.getCinn())
                                .kpp(from.getCkpp())
                                .accountNumber(from.getCean())
                                .bik(from.getCbik())
                                .bankName(from.getCbnam())
                                .swiftBankCode(from.getCbswt())
                                .build()
                )
                .documentId(from.getR120())
                .documentNumber(accountEntryNumberExtractor.extract(from))
                .debtorCode(from.getR233())
                .extendedDebtorCode(from.getR235())
                .purposeOfPayment(from.getR700())
                .debitCurrency(from.getR105())
                .creditCurrency(from.getRcccy())
                .debitAmount(from.getR320())
                .creditAmount(from.getR320C())
                .debitAmountRub(from.getR323())
                .creditAmountRub(from.getR324C())
                .documentDate(from.getR301())
                .transactionDate(from.getR302())
                .commitTransactionDate(Converters.convertToZonedDateTime(from.getTmst()))
                .build();
    }

    private static AccountingInfo convertToAccountingInfo(WSAccountMovementListGetOutParms from) {
        return AccountingInfo.builder()
                .incomingBalance(from.getBvv())
                .outgoingBalance(from.getBiv())
                .totalDebits(from.getPdv())
                .totalCredits(from.getPkv())
                .lastTransactionDate(from.getVfrl())
                .build();
    }
}
