package ru.alfabank.api.accounts.configuration;

import jakarta.servlet.http.HttpServletRequest;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Scope;
import org.springframework.web.context.WebApplicationContext;
import ru.alfabank.api.accounts.util.HttpHeaders;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.util.Optional;

@Configuration
@RequiredArgsConstructor
public class WSCommonParmsConfiguration {
    @Value("${ws.externalUserCodeValidation.enabled:false}")
    private boolean externalUserCodeValidationEnabled;

    private final ObjectFactory<WSProperties> properties;

    /**
     * Добавлена обработка необязательных HEADER:
     * X-UserID, при наличии переопределяется userID в WsCommonParms.
     * X-BranchNumber, при наличии переопределяется branchNumber в WsCommonParms.
     * X-ExternalSystemCode, при наличии переопределяется externalSystemCode в WsCommonParms.
     * X-ExternalUserCode, при наличии переопределяется externalUserCode в WsCommonParms.
     */
    @Bean
    @Scope(value = WebApplicationContext.SCOPE_REQUEST)
    public WSCommonParms wsCommonParms(HttpServletRequest currentRequest) {
        String userIdHeader = Optional.ofNullable(currentRequest.getHeader(HttpHeaders.X_USER_ID)).orElse(properties.getObject().getUserId());
        String branchNumberHeader = Optional.ofNullable(currentRequest.getHeader(HttpHeaders.X_BRANCH_NUMBER)).orElse(properties.getObject().getBranchNumber());
        String externalSystemCode = Optional.ofNullable(currentRequest.getHeader(HttpHeaders.X_EXTERNAL_SYSTEM_CODE)).orElse(properties.getObject().getExtSysCode());
        String externalUserCode = Optional.ofNullable(currentRequest.getHeader(HttpHeaders.X_EXTERNAL_USER_CODE)).orElse(properties.getObject().getExtUserCode());

        if (externalUserCodeValidationEnabled && (externalUserCode == null || externalUserCode.isBlank())) {
            throw new IllegalArgumentException("X-ExternalUserCode must not be null or empty");
        }

        WSCommonParms parms = new WSCommonParms();
        parms.setUserID(userIdHeader);
        parms.setBranchNumber(branchNumberHeader);
        parms.setExternalSystemCode(externalSystemCode);
        parms.setExternalUserCode(externalUserCode);
        return parms;
    }
}
