package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.entity.CustomerAccountCreationRequest;
import ru.alfabank.api.accounts.util.XmlFormatter;
import ru.alfabank.ws.cs.bi.wscodebusinessevent10.WSCodeBusinessEvent10PortType;
import ru.alfabank.ws.cs.bi.wscodebusinesseventinoutparms10.WSCodeBusinessEventAddInParms;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import javax.xml.datatype.DatatypeConfigurationException;
import javax.xml.datatype.DatatypeFactory;
import javax.xml.datatype.XMLGregorianCalendar;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

@Component
@RequiredArgsConstructor
public class CodeBusinessEventGateway {
    private static final String EVENT_TYPE = "28";
    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSCodeBusinessEvent10PortType wsCodeBusinessEvent10PortType;

    @Value("${was.wscodebusinessevent.branchDefault}")
    private String branchDefault;

    @Value("${was.wscodebusinessevent.externalSystem}")
    private String externalSystem;

    @Value("${business-event.is-voc-event:false}")
    private boolean isVocEventFormat;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public void addEvent(CustomerAccountCreationRequest request, String ean, ZonedDateTime eventTime) {
        String branch = request.getBranch();
        String operatorId = request.getUserId();
        if (isVocEventFormat) {
            branch = request.getEqMnemonic();
            operatorId = request.getUserLogin();
        }
        wsCodeBusinessEvent10PortType.wsCodeBusinessEventAdd(commonParms.getObject(),
                WSCodeBusinessEventAddInParms.builder().eventType(EVENT_TYPE)
                        .eventNumber(extractEventNumber(request))
                        .externalSys(externalSystem)
                        .cus(request.getCus())
                        .channelId(extractChannelId(request))
                        .managerId(request.getUserLogin())
                        .operatorId(operatorId)
                        .salePointId(branch)
                        .eventTime(toXMLGregorianCalendar(eventTime))
                        .value01(new BigDecimal(FORMATTER.format(request.getAccountsOpenTime())))
                        .value02(new BigDecimal(FORMATTER.format(eventTime)))
                        .freeFormat(XmlFormatter.getFreeFormat(ean, EVENT_TYPE, request))
                        .build());
    }

    private String extractEventNumber(CustomerAccountCreationRequest request) {
        return LocalDateTime.now().format(FORMATTER) + request.getCus();
    }

    private String extractChannelId(CustomerAccountCreationRequest request) {
        return request.getBranch().equals(branchDefault) ? "ICC" : "BRN";
    }

    private XMLGregorianCalendar toXMLGregorianCalendar(ZonedDateTime zonedDateTime) {
        try {
            return DatatypeFactory.newInstance().newXMLGregorianCalendar(zonedDateTime.toString());
        } catch (DatatypeConfigurationException e) {
            throw new RuntimeException(e);
        }
    }
}
